questions=[]
def q(cat,title,prompt,options,answer,explanation,code,nums,kind='choice',extra=None):
    refs=[{'law':code,'article':str(n)} for n in nums]
    item=dict(id='q'+str(len(questions)+1),category=cat,title=title,prompt=prompt,options=options,answer=answer,explanation=explanation,refs=refs,kind=kind,status='reviewed',reviewedAt='2026-10-01')
    item.update(extra or {})
    questions.append(item)

